async function makeClarityRequest(requestId, tabId) {
    return {
        requestId: requestId,
        url: 'https://www.example.com',
        method: 'GET',
        timeStamp: Date.now(),
        tabId: tabId,
        requestBody: await mimickGZIPData()
    };
}

